export type Event = 
	/** The shell is up; the core loads what it persisted. */
	| { type: "appStarted", content?: undefined }
	/** The app came to the foreground; stale data is refreshed. */
	| { type: "appBecameActive", content?: undefined }
	/**
	 * The web signed in through its own login form (`AuthMode::Cookie`); the core loads the
	 * new session. Native clients sign in through the core and never send it.
	 */
	| { type: "sessionStarted", content?: undefined }
	/** The user typed a server address on the add-server screen. */
	| { type: "serverAddressSubmitted", content: ServerAddress }
	| { type: "serverRemoved", content: ServerRef }
	| { type: "passwordSignInSubmitted", content: PasswordSignIn }
	| { type: "pairingStarted", content: ServerRef }
	| { type: "pairingCancelled", content?: undefined }
	/** The shell opened a `couchverse://` link (a scanned QR code or a tapped link). */
	| { type: "linkOpened", content: Link }
	| { type: "accountSelected", content: AccountRef }
	| { type: "signOutRequested", content: AccountRef }
	| { type: "devicesOpened", content?: undefined }
	| { type: "deviceRevoked", content: DeviceRef }
	| { type: "pairingApprovalOpened", content: UserCode }
	| { type: "pairingApproved", content: PairingApproval }
	| { type: "pairingDenied", content: UserCode }
	| { type: "displayLanguageChanged", content: LanguageChoice }
	/**
	 * A screen showing this surface appeared; the core loads it or, when cached, shows it
	 * and refreshes it.
	 */
	| { type: "screenOpened", content: Surface }
	| { type: "screenClosed", content: Surface }
	/** Pull to refresh. */
	| { type: "refreshRequested", content: Surface }
	/** The user scrolled near the end of a listing. */
	| { type: "browseMoreRequested", content: BrowseKey }
	/** The search field changed; the core waits for a pause in typing before searching. */
	| { type: "searchChanged", content: SearchText }
	| { type: "watchlistChanged", content: WatchlistChange }
	| { type: "noticeDismissed", content: NoticeRef }
	/** Something that may have earned an achievement happened (playback finished a title). */
	| { type: "achievementsCheckRequested", content: CheckRequest }
	/** The celebration on screen was seen. */
	| { type: "celebrationDismissed", content?: undefined }
	/** The viewer's profile appears on public pages and leaderboards, or not. */
	| { type: "profileVisibilityChanged", content: PublicChoice }
	| { type: "profileEditSubmitted", content: ProfileEdit }
	| { type: "passwordChangeSubmitted", content: PasswordForm }
	/** The user picked an image; the core asks the shell to upload it. */
	| { type: "imageChosen", content: ImageChoice }
	| { type: "imageRemoved", content: ImageSlotRef };

/** Something that happened in the shell: a user intent or a lifecycle change. */
